// Angel-only guard: only the configured Angel Telegram user ID may use this bot.
// Read from n8n credential 'AngelOS-Planner-Angel-UserId' (text credential, single value).
// If the credential is missing or empty, fall through to a safe rejection.

const angelUserIdCredential = $('AngelOS-Planner-Angel-UserId');
let angelUserId = null;
if (angelUserIdCredential && angelUserIdCredential.length > 0) {
  angelUserId = (angelUserIdCredential[0].json?.value ?? angelUserIdCredential[0].json ?? '').toString().trim();
}

const update = $input.first().json;
const fromId = update?.message?.from?.id ?? update?.callback_query?.from?.id ?? update?.edited_message?.from?.id ?? null;

if (!fromId) {
  return [{ json: { blocked: true, reason: 'No sender ID in update', reply: 'I could not identify who sent this.' } }];
}

if (!angelUserId || angelUserId === '') {
  return [{ json: { blocked: true, reason: 'Angel user ID not configured', reply: 'The Planner bot is not configured yet. Ask the owner to set the Angel Telegram user ID in n8n.' } }];
}

if (String(fromId) !== String(angelUserId)) {
  console.log(`[AngelOS Planner] Blocked message from user ${fromId} (Angel user ID is ${angelUserId}).`);
  return [{ json: { blocked: true, reason: 'Not Angel', reply: 'This bot is for Angel only.' } }];
}

let command = null;
let text = (update?.message?.text ?? update?.callback_query?.data ?? '').toString().trim();

if (text.startsWith('/')) {
  command = text.split(' ')[0].toLowerCase();
} else {
  command = 'chat';
}

return [{ json: {
  update,
  fromId: String(fromId),
  text,
  command,
  chatId: String(update?.message?.chat?.id ?? update?.callback_query?.message?.chat?.id ?? ''),
  blocked: false
} }];

// Parse the Hermes task creation response
const taskResponse = $input.first().json;
const taskId = taskResponse.id;
const status = taskResponse.status;

// Prepare data for the Hermes Builder execution branch
return [{
  json: {
    taskId: taskId,
    intent: $json.intent,
    text: $json.text,
    chatId: $json.chatId,
    command: $json.command,
    workspaceId: $json.workspaceId || 'default',
    taskCreated: true,
    taskStatus: status
  }
}];

// Format the Hermes Builder result for Telegram
const result = $input.first().json;
const taskId = result.taskId;
const intent = $json.intent;
const text = $json.text;
const chatId = $json.chatId;

let reply;

if (result.success) {
  if (result.status === 'done') {
    const r = result;

    if (intent === 'build' || intent === 'fix' || intent === 'review') {
      const parts = ['🔨 **Hermes Build Result**', ''];
      if (r.files_changed && r.files_changed.length) {
        parts.push(\`**Files (${r.files_changed.length}):**\`);
        r.files_changed.slice(0, 10).forEach(f => parts.push('- `' + f + '`'));
        if (r.files_changed.length > 10) parts.push('- ...and ' + (r.files_changed.length - 10) + ' more');
      }
      if (r.test_result) parts.push(\`**Tests:** ${r.test_result.status} (${r.test_result.passed} passed, ${r.test_result.failed} failed)\`);
      if (r.summary) parts.push(r.summary);
      reply = parts.join('\n');
    } else {
      reply = r.summary || '✅ Task completed. See AngelOS dashboard for details.';
    }
  } else {
    reply = '❌ Task failed: ' + (result.error || 'Unknown error');
  }
} else {
  reply = '❌ Hermes Builder execution failed: ' + (result.error || 'Unknown error');
}

return [{
  json: {
    chatId: chatId,
    text: reply,
    messageId: $json.update?.message?.message_id
  }
}];

// Format the AngelOS overview response for Telegram
const overview = $input.first().json;

const lines = [
  '🚦 **AngelOS Status**',
  '',
  'Pending approvals: ' + (overview.pendingApprovals ?? overview.pending_approvals ?? '?'),
  'Needs attention: ' + (overview.needsAttention ?? overview.needs_attention ?? '?')
];

// Pending approvals
const approvals = overview.pendingApprovalsItems ?? overview.pending_approvals_items ?? [];
if (approvals.length) {
  lines.push('');
  lines.push('**Pending approvals:**');
  approvals.slice(0, 5).forEach(a => {
    const name = a.clientName || a.content?.substring(0, 60) || '?';
    lines.push('- ' + name);
  });
  if (approvals.length > 5) lines.push('- ...and ' + (approvals.length - 5) + ' more');
}

// Attention items
const attention = overview.attentionItems ?? overview.attention_items ?? [];
if (attention.length) {
  lines.push('');
  lines.push('**Needs attention:**');
  attention.slice(0, 5).forEach(a => {
    lines.push('- [' + a.severity + '] ' + (a.title || '?'));
  });
}

return [{
  json: {
    chatId: $json.chatId,
    text: lines.join('\n'),
    messageId: $json.update?.message?.message_id
  }
}];

// Parse the Hermes Builder callback
// The callback comes from the AngelOS API after Hermes Builder finishes
const body = $input.first().json;

return [{
  json: {
    taskId: body.taskId,
    executionId: body.executionId,
    result: body.result || {},
    error: body.error,
    success: body.success,
    status: body.status
  }
}];

// Format the callback result for Telegram
const callback = $input.first().json;
const taskId = callback.taskId;

// We need to look up the original task to find the callback_url
// In production, this would query the AngelOS API
// For now, we format the result

let reply;
if (callback.success) {
  if (callback.status === 'done') {
    const r = callback.result;
    if (r.files_changed && r.files_changed.length) {
      const parts = ['🔨 **Hermes Build Result**', ''];
      parts.push('**Files:**');
      r.files_changed.slice(0, 10).forEach(f => parts.push('- `' + f + '`'));
      if (r.files_changed.length > 10) parts.push('- ...and more');
      if (r.test_result) parts.push('**Tests:** ' + r.test_result.status);
      if (r.summary) parts.push(r.summary);
      reply = parts.join('\n');
    } else {
      reply = r.summary || '✅ Task completed.';
    }
  } else {
    reply = '❌ Task failed: ' + (callback.error || 'Unknown error');
  }
} else {
  reply = '❌ Hermes Builder execution failed';
}

return [{
  json: {
    chatId: callback.chatId || '',
    text: reply,
    taskId: taskId
  }
}];
